import{_ as p,a0 as l,w as o,s as d,ao as c,I as e,x as a,a1 as t,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"使用 watch 和 tail 命令监视 Linux 上的活动 | LCTT x X-CMD","titleTemplate":false,"description":"使用 watch 和 tail 命令监视 Linux 上的活动 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 watch 和 tail 命令监视 Linux 上的活动 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 watch 和 tail 命令监视 Linux 上的活动 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20200303 Watching activity on Linux with watch and tail commands","title":"使用 watch 和 tail 命令监视 Linux 上的活动","tag":"202205","desc":""},"relativePath":"202205/20200303 Watching activity on Linux with watch and tail commands.md","filePath":"[post].md"}'),h={name:"202205/20200303 Watching activity on Linux with watch and tail commands.md"};function r(g,s,u,k,b,f){const n=l("Link");return o(),d("div",null,[s[15]||(s[15]=c(`<h1 id="使用-watch-和-tail-命令监视-linux-上的活动" tabindex="-1">使用 watch 和 tail 命令监视 Linux 上的活动 <a class="header-anchor" href="#使用-watch-和-tail-命令监视-linux-上的活动" aria-label="Permalink to “使用 watch 和 tail 命令监视 Linux 上的活动”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/07/091736ja5yt2yottef0kl4.jpg" alt=""></p><blockquote><p>watch 和 tail 命令可以帮助监视 Linux 系统上的活动。本文介绍了这两个命令的一些有用的使用方法。</p></blockquote><p><code>watch</code> 和 <code>tail</code> 命令为持续监视 Linux 系统上的活动提供了一些有趣的选项。</p><p>也就是说，你可以通过 <code>watch</code> 来显示谁已登录，并随着用户登录和注销不断更新，而不是仅仅提出问题并获得答案（例如询问 <code>who</code> 并获取当前登录用户的列表）。</p><p>使用 <code>tail</code>，你可以显示文件的底部并在添加内容时查看内容。这种监控一般非常有用，并且比定期运行命令所需的工作更少。</p><h3 id="使用-watch-命令" tabindex="-1">使用 watch 命令 <a class="header-anchor" href="#使用-watch-命令" aria-label="Permalink to “使用 watch 命令”">​</a></h3><p>使用 <code>watch</code> 的最简单示例之一是使用命令 <code>watch who</code>。你会看到一个列表，其中显示了谁登录了，以及他们登录的时间和登录位置。请注意，默认设置是每两秒更新一次显示（左上角），日期和时间（右上角）将按该间隔自行更新。用户列表将随着用户登录和注销而增长和缩小。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ watch who</span></span></code></pre></div><p>此命令将显示如下所示的登录列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Every 2.0s: who                              dragonfly: Thu Feb 27 10:52:00 2020</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nemo     pts/0        2020-02-27 08:07 (192.168.0.11)</span></span>
<span class="line"><span>shs      pts/1        2020-02-27 10:58 (192.168.0.5)</span></span></code></pre></div><p>你可以通过添加 <code>-n</code> 选项（例如 <code>-n 10</code>）来修改更新间的不同秒数，以修改更新间隔，从而获取较少的更新频率。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ watch -n 10 who</span></span></code></pre></div><p>上述命令将以新的间隔显示，并且显示的时间更新频率较低，从而使显示时间与所选间隔保持一致。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Every 10.0s: who                             dragonfly: Thu Feb 27 11:05:47 2020</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nemo     pts/0        2020-02-27 08:07 (192.168.0.11)</span></span>
<span class="line"><span>shs      pts/1        2020-02-27 10:58 (192.168.0.5)</span></span></code></pre></div><p>如果你希望仅查看命令的输出，而不是标题（前 2 行），则可以通过添加 <code>-t</code>（无标题）选项来省略这些行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ watch -t who</span></span></code></pre></div><p>然后，你的屏幕将显示如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nemo     pts/0        2020-02-27 08:07 (192.168.0.11)</span></span>
<span class="line"><span>shs      pts/1        2020-02-27 10:58 (192.168.0.5)</span></span></code></pre></div><p>如果每次运行监视的命令时，输出都是相同的，则只有标题行（如果未省略）会更改。其余显示的信息将保持不变。</p><p>如果你希望 <code>watch</code> 命令在它正在监视的命令的输出发生更新后立即退出，则可以使用 <code>-g</code>（将其视为“<ruby>离开<rt>go away</rt></ruby>”）选项。例如，如果你只是在等待其他人开始登录系统，则可以选择执行此操作。</p><p>你还可以使用 <code>-d</code>（<ruby>差异<rt>differences</rt></ruby>）选项突出显示显示输出中的更改。突出显示只会持续一个间隔（默认为 2 秒），但有助于引起你对更新的注意。</p><p>下面是一个更复杂的示例，该示例使用 <code>watch</code> 命令显示正在侦听连接的服务及其使用的端口。虽然输出不太可能更改，但它会提醒你任何新服务正在启动或关闭。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ watch &#39;sudo lsof -i -P -n | grep LISTEN&#39;</span></span></code></pre></div><p>值得注意的是，正在运行的命令需要用引号扩起来，以确保不会将 <code>watch</code> 命令的输出发送到 <code>grep</code> 命令。</p><p>使用 <code>watch -h</code> 命令将为你提供命令选项的列表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ watch -h</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Usage:</span></span>
<span class="line"><span> watch [options] command</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Options:</span></span>
<span class="line"><span>  -b, --beep             beep if command has a non-zero exit</span></span>
<span class="line"><span>  -c, --color            interpret ANSI color and style sequences</span></span>
<span class="line"><span>  -d, --differences[=&lt;permanent&gt;]</span></span>
<span class="line"><span>                         highlight changes between updates</span></span>
<span class="line"><span>  -e, --errexit          exit if command has a non-zero exit</span></span>
<span class="line"><span>  -g, --chgexit          exit when output from command changes</span></span>
<span class="line"><span>  -n, --interval &lt;secs&gt;  seconds to wait between updates</span></span>
<span class="line"><span>  -p, --precise          attempt run command in precise intervals</span></span>
<span class="line"><span>  -t, --no-title         turn off header</span></span>
<span class="line"><span>  -x, --exec             pass command to exec instead of &quot;sh -c&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span> -h, --help     display this help and exit</span></span>
<span class="line"><span> -v, --version  output version information and exit</span></span></code></pre></div><h3 id="使用-tail-f" tabindex="-1">使用 tail -f <a class="header-anchor" href="#使用-tail-f" aria-label="Permalink to “使用 tail -f”">​</a></h3><p><code>tail -f</code> 命令与 <code>watch</code> 有一些相同之处。它也会在添加文件时显示文件的底部和其他内容。你不必一次又一次地运行 <code>tail</code> 命令，而是运行一个命令并获得可重复更新显示视图的结果。例如，你可以使用如下命令查看系统日志：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tail -f /var/log/syslog</span></span></code></pre></div><p>某些文件（如 <code>/var/log/wtmp</code>）不适合这种类型的处理，因为它们的格式不是普通文本文件，但是通过组合 <code>watch</code> 和 <code>tail</code>，你可以获得类似的结果，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>watch &#39;who /var/log/wtmp | tail -20&#39;</span></span></code></pre></div><p>无论有多少用户仍处于登录状态，此命令都将只显示最近的 5 次登录。如果发生其他登录，显示结果将添加一行记录并删除顶行记录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Every 60.0s: who /var/log/wtmp | tail -5    dragonfly: Thu Feb 27 12:46:07 2020</span></span>
<span class="line"><span></span></span>
<span class="line"><span>shs      pts/0        2020-02-27 08:07 (192.168.0.5)</span></span>
<span class="line"><span>nemo     pts/1        2020-02-27 08:26 (192.168.0.5)</span></span>
<span class="line"><span>shs      pts/1        2020-02-27 10:58 (192.168.0.5)</span></span>
<span class="line"><span>nemo     pts/1        2020-02-27 11:34 (192.168.0.5)</span></span>
<span class="line"><span>dory     pts/1        2020-02-27 12:14 (192.168.0.5)</span></span></code></pre></div><p>对你有时可能想要监视的信息，无论监视进程、登录名还是系统资源，<code>watch</code> 和 <code>tail -f</code> 命令都可以提供自动更新视图，从而使监视任务变得更加容易。</p><hr>`,36)),e("p",null,[s[1]||(s[1]=a("via: ",-1)),t(n,{href:"https://www.networkworld.com/article/3529891/watching-activity-on-linux-with-watch-and-tail-commands.html"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3529891/watching-activity-on-linux-with-watch-and-tail-commands.html",-1)])]),_:1})]),e("p",null,[s[6]||(s[6]=a("作者：",-1)),t(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),t(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),t(n,{href:"https://github.com/Starryi"},{default:i(()=>[...s[4]||(s[4]=[a("Starryi",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),t(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[12]||(s[12]=a("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),t(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const x=p(h,[["render",r]]);export{y as __pageData,x as default};
